import { getPosts } from '../lib/posts'
import { cacheTag } from 'next/cache'

async function getCachedPosts() {
  'use cache'
  cacheTag('posts')
  return getPosts()
}

export default async function PostsPage() {
  const posts = await getCachedPosts()

  return (
    <main>
      <h1>All Posts</h1>
      <ul>
        {posts.map((post) => (
          <li key={post.id}>
            <h2>{post.title}</h2>
            <p>{post.content}</p>
          </li>
        ))}
      </ul>
    </main>
  )
}

